const logs = $input.item.json.data || [];

// Check for errors (status 500, 404, etc.)
const errors = logs.filter(log => {
  const status = log.status || log.statusCode;
  return status >= 400;
});

// Check for suspicious activity
const ipCounts = {};
logs.forEach(log => {
  ipCounts[log.ip] = (ipCounts[log.ip] || 0) + 1;
});

const suspiciousIPs = Object.entries(ipCounts)
  .filter(([ip, count]) => count > 20)
  .map(([ip, count]) => ({ ip, count }));

// Check for failed logins
const failedLogins = logs.filter(log => 
  log.url && log.url.includes('login') && log.status >= 400
);

const hasIssues = errors.length > 0 || suspiciousIPs.length > 0 || failedLogins.length > 0;

return [{
  json: {
    hasIssues,
    errors: errors.slice(0, 5),
    errorCount: errors.length,
    suspiciousIPs,
    failedLogins: failedLogins.slice(0, 5),
    failedLoginCount: failedLogins.length,
    totalLogs: logs.length
  }
}];

const data = $input.item.json;

let alert = `🚨 การแจ้งเตือน Error\n`;
alert += `เวลา: ${new Date().toLocaleString('th-TH')}\n\n`;

// Errors
if (data.errorCount > 0) {
  alert += `❌ Errors: ${data.errorCount} รายการ\n`;
  data.errors.forEach((log, i) => {
    alert += `${i + 1}. ${log.method} ${log.url}\n`;
    alert += `   Status: ${log.status} | IP: ${log.ip}\n`;
  });
  alert += `\n`;
}

// Suspicious IPs
if (data.suspiciousIPs.length > 0) {
  alert += `⚠️ Suspicious Activity:\n`;
  data.suspiciousIPs.forEach((item, i) => {
    alert += `${i + 1}. IP: ${item.ip} (${item.count} requests)\n`;
  });
  alert += `\n`;
}

// Failed logins
if (data.failedLoginCount > 0) {
  alert += `🔐 Failed Logins: ${data.failedLoginCount}\n`;
  data.failedLogins.forEach((log, i) => {
    alert += `${i + 1}. IP: ${log.ip} | Time: ${log.timestamp}\n`;
  });
  alert += `\n`;
}

alert += `📊 Total logs checked: ${data.totalLogs}`;

return [{
  json: {
    alert
  }
}];
